package com.vinaxmart.controller; import com.vinaxmart.service.AuthService; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService s; public AuthController(AuthService s){this.s=s;} public record Req(@NotBlank String name,@Email String email,@Size(min=6) String password){} public record Login(@Email String email,@NotBlank String password){} @PostMapping("/register") public Map<String,Object> reg(@RequestBody Req r){return s.register(r.name(),r.email(),r.password());} @PostMapping("/login") public Map<String,Object> login(@RequestBody Login r){return s.login(r.email(),r.password());}}